/* From Uiverse.io by TemRevil  - Tags: simple, action, loading, loader, smooth, code, neon, game */
.__UIV_SCOPE__ .loading-box {
  width: 150px;
  height: 150px;
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 10px;
}

.__UIV_SCOPE__ .WH {
  width: 20px;
  height: 70px;
}
.__UIV_SCOPE__ .color {
  background-color: #ff5100;
}
.__UIV_SCOPE__ .animation {
  animation: Loading 1s infinite cubic-bezier(0.68, -0.55, 0.27, 1.55);
}

@keyframes Loading {
  0% {
    height: 0;
  }
  25% {
    height: 70px;
  }
  50% {
    height: 70px;
    transform: rotate(10deg);
  }
  75% {
    height: 70px;
    transform: rotate(0deg);
  }
  100% {
    height: 0;
  }
}
